#!/usr/bin/env bash
# =============================================================================
#  Y2K DAW — Self-Extracting Installer  v10
#  Session Schema v2 · Atomic Save · Wired Undo · Crash Recovery
#
#  92 files | 220 test cases | 7 new session files
#
#  USAGE
#  ─────────────────────────────────────────────────────────────────────────────
#    Extract only:   bash build_y2k_daw_v10.sh [target-dir]
#    Build:          bash build_y2k_daw_v10.sh [target-dir] --build
#    Build + Test:   bash build_y2k_daw_v10.sh [target-dir] --test
#
#  WHAT'S NEW IN V10
#  ─────────────────────────────────────────────────────────────────────────────
#
#  1. SESSION SCHEMA v2 (SessionSchema)
#     engine/y2k_engine/session/session_schema.h/cpp
#     • schemaVersion = "2.0" in every saved file
#     • migrate() upgrades v1.0 → v2.0 automatically at load time
#       - Adds Routing subtree (buses, sends, fader state)
#       - Adds Insert/Send subtrees to each track
#       - Idempotent: no-op on already-current files
#     • Full ProjectRouting serialization (from v9 mixer):
#       master bus + non-master buses + track routing (vol/pan/mute/solo),
#       send slots (level + preFader) + insert chains
#     • deserialise() returns LoadResult { status, session, routing,
#       migrationLog } — typed error, not silent corruption
#
#  2. ATOMIC SAVE (zero crash-window)
#     SessionSchema::atomicSave(session, routing, destFile)
#       1. Serialise → XML in memory
#       2. Write to destFile.tmp
#       3. platformFsync()  — flush OS write buffer (fsync / FlushFileBuffers)
#       4. rename()  .tmp → destFile  (atomic on POSIX)
#     Original file untouched on failure. No .tmp orphan on success.
#
#  3. AUTO-SAVE + CRASH RECOVERY (AutoSaveManager)
#     engine/y2k_engine/session/auto_save_manager.h
#     • juce::Thread background save every 30s (configurable)
#     • Fires only when dirty_ atomic flag is set
#     • Writes to <bundle>/autosave.xml — never touches project.xml
#     • AutoSaveManager::recoveryAvailable(bundleDir) for startup check
#     • loadRecovery() / discardRecovery() — full control from UI code
#     • onFullSaveCompleted() → clears dirty, removes autosave.xml
#
#  4. FULLY WIRED UNDO (SessionCommandBus)
#     engine/y2k_engine/session/session_command_bus.h
#     v9 had UndoAction with empty undo()/redo() stubs.
#     v10 routes ALL mutations through SessionCommandBus:
#       setTrackVolume / setTrackPan / setTrackMuted / setTrackSoloed
#       setTempo / addTrack / removeTrack / moveClip / setBusVolume
#     Every call: creates LambdaUndoAction, calls undo_.perform(),
#     mutates state, marks autoSave dirty, fires onSessionChanged /
#     onRoutingChanged callbacks.
#     onRoutingChanged → AudioEngine::setRouting() → GraphCompiler → PDC
#
#  5. AUDIOENGINE v10 API
#     saveProject(file)    — atomicSave + clear dirty
#     loadProject(file)    — deserialise + migrate + rewire
#     startAutoSave(dir)   — starts background thread
#     commandBus()         — SessionCommandBus* for UI mutations
#     recoveryAvailable()  — startup crash check
#     loadRecovery()       — restore from autosave.xml
#
#  ALL V9 SYSTEMS RETAINED
#  ─────────────────────────────────────────────────────────────────────────────
#  ALL V8 SYSTEMS RETAINED
#     • Immutable GraphState + atomic swap
#     • Unified ParameterBank 4-layer model
#     • Sample-accurate TransportEngine
#     • VoiceManager 16-voice ADSR pool
#     • Lock-free MIDI queue
#     • Automation hardening — auto layer never touches base
#     • ClipScheduler: exact BPM scheduling, atomic<shared_ptr> swap
#     • BondiSynth: ParameterBank integrated, no setSize in RT
#
#  RT SAFETY AUDIT
#  ─────────────────────────────────────────────────────────────────────────────
#     • Zero setSize() in any process() method
#     • Zero std::mutex in any RT path
#     • PDC injection: non-RT only (inside commitState)
#     • LatencyCompensator::process(): vector read only, no resize
#     • MeterTap::process(): stack-only computation, atomic stores
#     • SumNode::process(): FloatVectorOperations (no alloc)
#     • TrackFaderNode::process(): smoothed ramps, no alloc
#     • BondiSynth::process(): bank_.resolved() reads, no alloc
#
#  TEST COVERAGE: 220 TEST_CASEs
#  ─────────────────────────────────────────────────────────────────────────────
#     graph/    test_pdc.cpp (11)  test_processor_graph.cpp (11)
#               test_graph_state.cpp (6)
#     meter/    test_meter_tap.cpp (13)
#     mixer/    test_graph_compiler.cpp (10)  test_sum_node.cpp (8)
#               test_track_fader_node.cpp (10)  test_track_model.cpp (9)
#               test_track_gain.cpp (9)
#     dsp/      test_parameter_state.cpp (10)  test_voice_manager.cpp (9)
#               test_smooth_parameter.cpp (3)  test_sine_osc.cpp (8)
#     engine/   test_transport_engine.cpp (9)  test_automation.cpp (7)
#               test_autoplay.cpp (6)  test_midi_learn.cpp (8)
#               test_session.cpp (6)  test_undo.cpp (8)
#     record/   test_audio_recorder.cpp (6)  test_midi_recorder.cpp (6)
#               test_audio_file_importer.cpp (4)
# =============================================================================
set -euo pipefail

# ── Argument parsing ──────────────────────────────────────────────────────────
TARGET="${1:-y2k-daw}"
DO_BUILD=0
DO_TEST=0
for arg in "$@"; do
  [[ "$arg" == "--build" ]] && DO_BUILD=1
  [[ "$arg" == "--test"  ]] && DO_BUILD=1 && DO_TEST=1
done

# ── Terminal colours ──────────────────────────────────────────────────────────
BONDI='\033[38;2;0;113;227m'
LIME='\033[38;2;166;226;46m'
TANG='\033[38;2;255;149;0m'
GRAPE='\033[38;2;175;82;222m'
RESET='\033[0m'
BOLD='\033[1m'

echo ""
echo -e "${BONDI}${BOLD}  Y2K DAW v10 — PDC + Track Layer + Bus Model + Metering${RESET}"
echo -e "${LIME}  SumNode · TrackFaderNode · GraphCompiler · MeterTap · LatencyComp${RESET}"
echo -e "${TANG}  92 files | 220 tests | Atomic save + wired undo + crash recovery${RESET}"
echo ""

# ── Target directory ──────────────────────────────────────────────────────────
if [ -d "$TARGET" ]; then
    echo -e "${TANG}  Directory \"$TARGET\" already exists — overwrite? [y/N] ${RESET}\c"
    read -r confirm
    [[ "$confirm" != "y" && "$confirm" != "Y" ]] && echo "Aborted." && exit 0
    rm -rf "$TARGET"
fi

mkdir -p "$TARGET"
echo -e "${BONDI}-> Extracting to ./$TARGET${RESET}"
echo ""

# ── Source tree ───────────────────────────────────────────────────────────────
mkdir -p "$TARGET/app"
mkdir -p "$TARGET/cmake"
mkdir -p "$TARGET/engine/y2k_dsp"
mkdir -p "$TARGET/engine/y2k_dsp/effects"
mkdir -p "$TARGET/engine/y2k_dsp/generators"
mkdir -p "$TARGET/engine/y2k_dsp/graph"
mkdir -p "$TARGET/engine/y2k_dsp/instruments"
mkdir -p "$TARGET/engine/y2k_dsp/meter"
mkdir -p "$TARGET/engine/y2k_dsp/mixer"
mkdir -p "$TARGET/engine/y2k_dsp/param"
mkdir -p "$TARGET/engine/y2k_dsp/recording"
mkdir -p "$TARGET/engine/y2k_dsp/voice"
mkdir -p "$TARGET/engine/y2k_engine"
mkdir -p "$TARGET/engine/y2k_engine/graph_synth"
mkdir -p "$TARGET/engine/y2k_engine/mixer"
mkdir -p "$TARGET/engine/y2k_engine/session"
mkdir -p "$TARGET/prototype"
mkdir -p "$TARGET/tests"
mkdir -p "$TARGET/tests/dsp"
mkdir -p "$TARGET/tests/engine"
mkdir -p "$TARGET/tests/graph"
mkdir -p "$TARGET/tests/meter"
mkdir -p "$TARGET/tests/mixer"
mkdir -p "$TARGET/tests/recording"
mkdir -p "$TARGET/tests/session"
mkdir -p "$TARGET/ui/y2k_ui"
mkdir -p "$TARGET/ui/y2k_ui/components"
mkdir -p "$TARGET/ui/y2k_ui/screens"

# ── File extraction (base64-encoded) ─────────────────────────────────────────
echo -e "${LIME}  ok${RESET}  CMakeLists.txt"
base64 -d << 'B64EOF' > "$TARGET/CMakeLists.txt"
