echo ""
echo -e "${BONDI}${BOLD}  ✓ 92 files extracted to ./$TARGET${RESET}"
echo ""

NCPU=$(nproc 2>/dev/null || sysctl -n hw.ncpu 2>/dev/null || echo 4)

if [[ "$DO_BUILD" == "1" ]]; then
    echo -e "${BONDI}${BOLD}-> Configuring...${RESET}"
    TEST_FLAG=""; [[ "$DO_TEST" == "1" ]] && TEST_FLAG="-DY2K_BUILD_TESTS=ON"
    cmake -B "$TARGET/build" -S "$TARGET" -DCMAKE_BUILD_TYPE=Release $TEST_FLAG 2>&1 | tail -10
    echo -e "${BONDI}${BOLD}-> Building ($NCPU cores)...${RESET}"
    cmake --build "$TARGET/build" --config Release -j"$NCPU" 2>&1 | tail -20
    if [[ "$DO_TEST" == "1" ]]; then
        echo -e "${BONDI}${BOLD}-> Running 112 tests...${RESET}"
        ctest --test-dir "$TARGET/build" --output-on-failure -C Release
    fi
    BIN=$(find "$TARGET/build" -name "Y2K DAW.app" -o -name "Y2KDAW" -o -name "Y2KDAW.exe" 2>/dev/null | head -1)
    [[ -n "$BIN" ]] && echo -e "${LIME}${BOLD}  ✓ Binary: $BIN${RESET}"
else
    echo -e "${BOLD}  ═══ BUILD & RUN ═══${RESET}"
    echo ""
    echo -e "  ${BOLD}Configure + Build:${RESET}"
    echo -e "    ${BONDI}cmake -B build -S $TARGET -DCMAKE_BUILD_TYPE=Release${RESET}"
    echo -e "    ${BONDI}cmake --build build -j\$(nproc)${RESET}"
    echo ""
    echo -e "  ${BOLD}Run:${RESET}"
    echo -e "    ${GRAPE}macOS:   open build/Y2KDAW_artefacts/Release/Y2K\\ DAW.app${RESET}"
    echo -e "    ${GRAPE}Linux:   ./build/Y2KDAW_artefacts/Release/Y2K\\ DAW${RESET}"
    echo -e "    ${GRAPE}Windows: build\\Y2KDAW_artefacts\\Release\\Y2K DAW.exe${RESET}"
    echo ""
    echo -e "  ${BOLD}Tests (112 cases):${RESET}"
    echo -e "    ${BONDI}cmake -B build -S $TARGET -DY2K_BUILD_TESTS=ON${RESET}"
    echo -e "    ${BONDI}cmake --build build && ctest --test-dir build --output-on-failure${RESET}"
    echo ""
    echo -e "  ${BOLD}Local JUCE (offline build):${RESET}"
    echo -e "    ${BONDI}cmake -B build -S $TARGET -DJUCE_DIR=/path/to/JUCE${RESET}"
    echo ""
    echo -e "  ${LIME}On launch:${RESET}"
    echo -e "    • 440Hz sine (proof-of-life) plays immediately — via VoiceManager"
    echo -e "    • TransportEngine drives beat position from sample count"
    echo -e "    • Automation sweeps frequency 220→880Hz using automation layer"
    echo -e "    • Track volume breathes — automation layer only, base untouched"
    echo -e "    • Kontrol keyboard → lock-free MIDI queue → VoiceManager"
    echo -e "    • Right-click knob → MIDI Learn (writes to midi layer, not base)"
    echo -e "    • Graph edits swap GraphState atomically — no audio dropout"
    echo ""
    echo -e "  ${BOLD}Architecture:${RESET}"
    echo -e "    UI ──[pushParameterEvent layer=0]──→ ParameterBank.base"
    echo -e "    Automation ──[setParameterAutomation]──→ ParameterBank.automation"
    echo -e "    MIDI ──[setParameterMidi]──→ ParameterBank.midi"
    echo -e "    DSP reads resolvedParameter() = clamp(base + auto + mod + midi)"
    echo ""
fi
